
(()=>{const S7=["data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,"],col=['#FFA51F','#BFE36B','#FF8A7A','#FFD84A','#8FB5FF','#6FE0C2','#C9A7FF'],sh=['c','d','p','s','t'],P=[[46,10],[93,64],[60,88],[80,12]];
$('#g7').innerHTML=SUB.map((f,i)=>{let q='';for(let k=0;k<4;k++)q+=`<i class="pt ${sh[(i*2+k*3)%5]}" style="left:${(P[k][0]+i*9)%88+4}%;top:${k%2?84:3}%;--dl:${((i+k)*.35).toFixed(2)}s;--sz:${14+(i+k)%3*3}px"></i>`;if(f.k)q+='<i class="pt s" style="left:91%;top:66%;--sz:28px;--dl:.2s"></i>';
return `<button class="sb${f.k?' k':''}" data-k="S${i}" style="--ac:${col[i]};--i:${i}">${q}<img class="m" src="${S7[i]}" alt=""><span class="tx"><h3>${f.n}</h3><p>${f.d}</p></span><span class="ar" aria-hidden="true">↗</span><span class="sr">${f.k||f.t||''}</span></button>`}).join('');
$$('.sb').forEach(c=>{io.observe(c);if(FINE&&!RM){c.addEventListener('pointermove',e=>{const r=c.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;c.style.transform=`perspective(800px) rotateX(${-y*9}deg) rotateY(${x*11}deg) translateY(-4px)`});c.addEventListener('pointerleave',()=>c.style.transform='')}});
const pg=document.createElement('div');pg.id='pg';pg.setAttribute('aria-hidden','true');document.body.append(pg);
addEventListener('scroll',()=>pg.style.setProperty('--p',scrollY/Math.max(1,document.documentElement.scrollHeight-innerHeight)),{passive:true});
if(!RM)document.addEventListener('pointerdown',e=>{const b=e.target.closest('.btn');if(!b)return;const r=b.getBoundingClientRect(),s=document.createElement('span');s.className='rip';s.style.left=e.clientX-r.left+'px';s.style.top=e.clientY-r.top+'px';b.append(s);setTimeout(()=>s.remove(),700)})})();
